PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    LastLevel : INT := 0;
    PumpTimer : TON;
END_VAR

IF Level >= HighLimit THEN
    ValveOut := TRUE;
    PumpIn := FALSE;
ELSE
    ValveOut := FALSE;

    IF Level <= LowLimit THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    IF Level >= HighLimit AND LastLevel < HighLimit THEN
        PumpTimer(IN := TRUE, PT := T#5s);
    ELSIF Level < HighLimit AND LastLevel >= HighLimit THEN
        PumpTimer(IN := FALSE);
    END_IF;

    PumpIn := NOT (PumpIn OR PumpTimer.Q);
END_IF;

LastLevel := Level;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    hysteresis_high : INT := 85;
    hysteresis_low : INT := 15;
    safety_timer : TON;
END_VAR

safety_timer(IN := NOT prev_PumpIn AND PumpIn, PT := T#1s);

IF safety_timer.Q THEN
    PumpIn := FALSE;
END_IF;

IF Level >= hysteresis_high THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= hysteresis_low THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := prev_PumpIn;
    ValveOut := prev_ValveOut;
END_IF;

prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

