PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    DoorAState : BOOL := FALSE;
    DoorBState : BOOL := FALSE;
END_VAR

DoorATimer(IN := OpenA_Cmd AND NOT DoorBState, PT := T#0s);
DoorBTimer(IN := OpenB_Cmd AND NOT DoorAState, PT := T#0s);

IF DoorATimer.Q THEN
    DoorAState := TRUE;
    DoorBState := FALSE;
ELSIF DoorBTimer.Q THEN
    DoorAState := FALSE;
    DoorBState := TRUE;
ELSE
    DoorAState := FALSE;
    DoorBState := FALSE;
END_IF;

DoorA := DoorAState;
DoorB := DoorBState;
END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    PriorityDoor : INT;
END_VAR

DoorATimer(IN := OpenA_Cmd AND NOT DoorB, PT := T#0s);
DoorBTimer(IN := OpenB_Cmd AND NOT DoorA, PT := T#0s);

IF DoorATimer.Q THEN
    PriorityDoor := 1;
ELSIF DoorBTimer.Q THEN
    PriorityDoor := 2;
ELSE
    PriorityDoor := 0;
END_IF;

CASE PriorityDoor OF
    1: 
        DoorA := TRUE;
        DoorB := FALSE;
    2: 
        DoorA := FALSE;
        DoorB := TRUE;
    ELSE: 
        DoorA := FALSE;
        DoorB := FALSE;
END_CASE;
END_PROGRAM

