PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    T_green_NS, T_yellow_NS, T_allred_NS, T_green_EW, T_yellow_EW, T_allred_EW : TON;
END_VAR

T_green_NS(IN := State = 0, PT := T#2s);
T_yellow_NS(IN := State = 1, PT := T#1s);
T_allred_NS(IN := State = 2, PT := T#1s);
T_green_EW(IN := State = 3, PT := T#2s);
T_yellow_EW(IN := State = 4, PT := T#1s);
T_allred_EW(IN := State = 5, PT := T#1s);

NS_G := NOT T_green_EW.Q AND NOT T_yellow_EW.Q AND T_green_NS.Q;
NS_Y := NOT T_green_EW.Q AND NOT T_yellow_EW.Q AND T_yellow_NS.Q;
NS_R := NOT T_green_EW.Q AND NOT T_yellow_EW.Q AND (T_allred_NS.Q OR T_allred_EW.Q);

EW_G := NOT T_green_NS.Q AND NOT T_yellow_NS.Q AND T_green_EW.Q;
EW_Y := NOT T_green_NS.Q AND NOT T_yellow_NS.Q AND T_yellow_EW.Q;
EW_R := NOT T_green_NS.Q AND NOT T_yellow_NS.Q AND (T_allred_NS.Q OR T_allred_EW.Q);

IF T_green_NS.Q THEN
    State := 1;
ELSIF T_yellow_NS.Q THEN
    State := 2;
ELSIF T_allred_NS.Q THEN
    State := 3;
ELSIF T_green_EW.Q THEN
    State := 4;
ELSIF T_yellow_EW.Q THEN
    State := 5;
ELSIF T_allred_EW.Q THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    T_Green_NS : TON;
    T_Green_EW : TON;
    T_Yellow_NS : TON;
    T_Yellow_EW : TON;
    T_AllRed : TON;
END_VAR

T_Green_NS(IN := State = 0 OR State = 3, PT := T#2s);
T_Green_EW(IN := State = 3 OR State = 0, PT := T#2s);
T_Yellow_NS(IN := State = 1 OR State = 4, PT := T#1s);
T_Yellow_EW(IN := State = 4 OR State = 1, PT := T#1s);
T_AllRed(IN := State = 2 OR State = 5, PT := T#1s);

NS_G := NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.Q AND (State = 0 OR State = 3);
NS_Y := NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.Q AND (State = 1 OR State = 4);
NS_R := T_AllRed.Q OR (NOT T_Green_NS.Q AND NOT T_Yellow_NS.Q AND NOT T_AllRed.Q AND (State = 2));

EW_G := NOT T_Green_EW.Q AND NOT T_Yellow_EW.Q AND NOT T_AllRed.Q AND (State = 0 OR State = 3);
EW_Y := NOT T_Green_EW.Q AND NOT T_Yellow_EW.Q AND NOT T_AllRed.Q AND (State = 1 OR State = 4);
EW_R := T_AllRed.Q OR (NOT T_Green_EW.Q AND NOT T_Yellow_EW.Q AND NOT T_AllRed.Q AND (State = 2));

CASE State OF
    0: State := 1;
    1: State := 2;
    2: State := 3;
    3: State := 4;
    4: State := 5;
    5: State := 0;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    GreenTimer, YellowTimer, AllRedTimer : TON;
END_VAR

GreenTimer(IN := State = 0 OR State = 3, PT := T#2s);
YellowTimer(IN := State = 1 OR State = 4, PT := T#1s);
AllRedTimer(IN := State = 2 OR State = 5, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := TRUE;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := TRUE;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE;

State := (State + 1) MOD 6;
