        NS_R := NOT NS_G AND NOT NS_Y;

        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

    1:
        T_green_NS(IN := FALSE, PT := T#0s);
        T_yellow_NS(IN := TRUE, PT := T#1s);
        T_allred_NS(IN := FALSE, PT := T#0s);

        NS_G := FALSE;
        NS_Y := T_yellow_NS.Q;
        NS_R := NOT NS_G AND NOT NS_Y;

        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;

    2:
        T_green_NS(IN := FALSE, PT := T#0s);
