        EW_Y := FALSE;
        EW_R := TRUE;

    3:
        T_green_EW(IN := TRUE, PT := T#2s);
        T_yellow_EW(IN := FALSE, PT := T#0s);
        T_allred_EW(IN := FALSE, PT := T#0s);

        EW_G := T_green_EW.Q;
        EW_Y := FALSE;
        EW_R := NOT EW_G AND NOT EW_Y;

        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;

    4:
        T_green_EW(IN := FALSE, PT := T#0s);
        T_yellow_EW(IN := TRUE, PT := T#1s);
        T_allred_EW(IN := FALSE, PT := T#0s);

        EW_G := FALSE;
        EW_Y := T_yellow_EW.Q;
        EW_R := NOT EW_G AND NOT EW_Y;

        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;

    5:
        T_green_EW(IN := FALSE, PT := T#0s);
        T_yellow_EW(IN := FALSE, PT := T#0s);
        T_allred_EW(IN := TRUE, PT := T#1s);

        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := T_allred_EW.Q;

        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
END_CASE;
