PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    HeatTimer : TON;
    ReactTimer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        ReactTimer(IN := TRUE, PT := PT_REACT);
        IF ReactTimer.Q THEN
            State := 4;
        END_IF;

    4: -- Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

