        END_IF;
    1:
        IF FillTimer.Q OR Level >= LVL_HIGH THEN
            FillValve := FALSE;
            State := 2;
            HeatTimer(IN := TRUE, PT := T#0s);
        END_IF;
    2:
        IF HeatTimer.Q AND Temp >= TEMP_SET THEN
            Heater := TRUE;
            Agitator := TRUE;
