        IF ReactTimer.Q THEN
            Heater := TRUE;
            Agitator := TRUE;
            State := 4;
            DrainTimer(IN := TRUE, PT := T#0s);
        END_IF;
    4:
        IF DrainTimer.Q OR Level <= LVL_LOW THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

FillValve := (State = 1);
Heater := (State = 2 OR State = 3);
Agitator := (State = 2 OR State = 3);
DrainValve := (State = 4);

END_PROGRAM

PROGRAM batch_reactor
