END_VAR

T1(IN := NOT EStop AND StartBatch, PT := T#1s);

CASE State OF
    0:  // Idle
        IF EStop THEN
            State := 0;
        ELSIF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1:  // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT StartBatch OR EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2:  // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR NOT StartBatch OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 3;
        END_IF;

    3:  // React
        Heater := TRUE;
        Agitator := TRUE;
        IF T1.Q OR NOT StartBatch OR EStop THEN
            Heater := FALSE;
            Agitator := FALSE;
            State := 4;
        END_IF;

    4:  // Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT StartBatch OR EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (State = 2 OR State = 3) THEN
    Heater := FALSE;
