    StarK : BOOL;
    DeltaK : BOOL;
END_VAR

VAR
    State : INT := 0;
    PT_STAR : TIME := T#3s;
    StarTimer : TON;
END_VAR

StarTimer(IN := NOT EStop AND StartPB AND (State = 0 OR State = 1), PT := PT_STAR);

CASE State OF
    0:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
        IF NOT EStop THEN
            IF StartPB THEN
                State := 1;
            END_IF;
        END_IF;

