        DeltaK := FALSE;
        IF StarTimer.Q THEN
            State := 2;
        END_IF;

    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

