    PedReq : BOOL;
END_VAR
VAR_OUTPUT
    CarGreen : BOOL;
    CarYellow : BOOL;
    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR
VAR
    State : INT := 0;
    GreenTimer : TON;
    YellowTimer : TON;
    WalkTimer : TON;
    PT_GREEN : TIME := T#3s;
    PT_YELLOW : TIME := T#2s;
    PT_WALK : TIME := T#3s;
END_VAR

GreenTimer(IN := TRUE, PT := PT_GREEN);
YellowTimer(IN := FALSE, PT := PT_YELLOW);
WalkTimer(IN := FALSE, PT := PT_WALK);

CASE State OF
    0:
        CarGreen := TRUE;
        CarYellow := FALSE;
        CarRed := FALSE;
        PedWalk := FALSE;
        IF GreenTimer.Q AND PedReq THEN
            State := 1;
        END_IF;
    1:
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;
        IF YellowTimer.Q THEN
            State := 2;
        END_IF;
    2:
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;
        IF WalkTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

