    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

PurgeTimer(IN := NOT EStop AND StartPB AND State = 0, PT := T#3s);
IgnitionTimer(IN := NOT EStop AND State = 2, PT := T#2s);

CASE State OF
    0:
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT EStop AND StartPB THEN
            State := 1;
        END_IF;

    1:
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;

    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgnitionTimer.Q AND Flame THEN
            State := 3;
        ELSIF IgnitionTimer.Q OR NOT Flame THEN
            State := 0;
        END_IF;

    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

