PurgeTimer(IN := State = 1 AND NOT EStop, PT := T#3s);
IgnitionTimer(IN := State = 2 AND NOT EStop, PT := T#2s);

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        Fan := TRUE;
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;
    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgnitionTimer.Q AND Flame THEN
            State := 3;
        ELSIF IgnitionTimer.Q OR NOT Flame THEN
            State := 0;
        END_IF;
    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame THEN
            State := 0;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
    Fan := FALSE;
    Fuel := FALSE;
    Ignition := FALSE;
END_IF;

