T_EStopRelease(IN := NOT EStop, PT := T#1s);

Pump1 := FALSE;
Pump2 := FALSE;

IF EStop THEN
    Lead := 0;
    PrevDemand := FALSE;
ELSIF Demand AND NOT PrevDemand THEN
    Lead := 1 - Lead;
