PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpeningTimer : TON;
    ClosingTimer : TON;
END_VAR

OpeningTimer(IN := NOT CloseLimit AND NOT Obstruction AND OpenCmd AND (State = 0 OR State = 2), PT := T#0.5s);
ClosingTimer(IN := NOT OpenLimit AND NOT Obstruction AND CloseCmd AND (State = 0 OR State = 1), PT := T#0.5s);

CASE State OF
    0:  // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
        END_IF;

    1:  // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF;

    2:  // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

