    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpenTimer : TON;
    CloseTimer : TON;
END_VAR

CASE State OF
    0:  // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
            OpenTimer(IN := TRUE, PT := T#0s);
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
            CloseTimer(IN := TRUE, PT := T#0s);
