    1:  // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF;
        IF NOT OpenCmd THEN
            State := 0;
        END_IF;

    2:  // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            State := 0;
        END_IF;
        IF NOT CloseCmd THEN
            State := 0;
        END_IF;
END_CASE;

