    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
    T_Reset : TON;
END_VAR

T_Reset(IN := Reset, PT := T#1ms);

IF T_Reset.Q THEN
    Count := 0;
    Done := FALSE;
END_IF;

PrevTrigger := Trigger;

IF NOT PrevTrigger AND Trigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

Done := (Count = 3);
